from g69_core import bars_fig, make_lesson, make_q, table_fig


def _q(b: int, n: int, d: str, p: str, c: str, w: list[str], e: str, h: str = '', fig=None):
    return make_q(f'TA9-B{b:02d}-{n:03d}', d, p, c, w, e, 'Tiếng Anh 9', h, fig)


